window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9dcac809bcbb2b0d"]={"versions": [{"id": "FIG-9dcac809bcbb2b0d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzendiagramm) zur Spezifikation einer exemplarischen ECU-Konfigurationsdefinition (<code>ECU Configuration Definition</code>) innerhalb der AUTOSAR Classic Platform (TPS ECU Configuration). Das Diagramm illustriert die relationale Einbettung eines konkreten BSW-Moduls (<code>Rte</code>) und dessen Konfigurationscontainer (<code>RteGeneration</code>) ausgehend von einer zentralen Definitionskollektion.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert drei Entitäten (UML-Objektinstanzen):</p>\n<ul class=\"fig-list\">\n<li><code>AUTOSARParameterDefinition : EcucDefinitionCollection</code>: Zentrale Sammlung aller Moduldefinitionen eines AUTOSAR-Systems.</li>\n<li><code>Rte : EcucModuleDef</code>: Moduldefinition für die Runtime Environment (RTE) mit den Attributwerten <code>upperMultiplicity = 1</code> und <code>lowerMultiplicity = 0</code>.</li>\n<li><code>RteGeneration : EcucParamConfContainerDef</code>: Containerdefinition für Generierungsparameter der RTE mit den Attributwerten <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen zwischen den Entitäten:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet-assoziative Referenz <code>+module</code> von <code>AUTOSARParameterDefinition</code> auf <code>Rte : EcucModuleDef</code> mit offener Pfeilspitze.</li>\n<li>Kompositionsbeziehung (ausgefüllte schwarze Raute) mit Rollenbezeichnung <code>+container</code> von <code>Rte : EcucModuleDef</code> zu <code>RteGeneration : EcucParamConfContainerDef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Definitionsmodell ohne dynamischen Laufzeit- oder Sequenzablauf. Die Instanzen bilden zur Entwurfs- bzw. Konfigurationszeit die hierarchische Metamodellstruktur ab: Eine <code>EcucDefinitionCollection</code> referenziert optionale Moduldefinitionen (<code>[0..1]</code>), welche per Komposition verpflichtende Container (<code>[1..1]</code>) zur Strukturierung der BSW-Konfigurationsparameter aggregieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert normativ die Struktur von Parameterspezifikationen in AUTOSAR ECU-Konfigurationsbeschreibungen (<code>.arxml</code>):</p>\n<ul class=\"fig-list\">\n<li><code>EcucModuleDef</code> dient als formale Definitionsgrundlage für konfigurierbare Parameter eines BSW-Moduls.</li>\n<li>Die Multiplizitäten regeln die Instanziierungsbedingungen: Das RTE-Modul ist im Kontext der Definition optional instanziierbar (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), während der Container <code>RteGeneration</code> bei Vorhandensein des Moduls genau einmal definiert sein muss (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Werkzeughersteller und Konfiguratoren müssen diese Kardinalitäten bei der Validierung von ECU-Konfigurationswerten gegen die Definitionsdateien zwingend durchsetzen.</li>\n</ul>"}, {"id": "FIG-77986867314985a1", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzendiagramm) zur Spezifikation einer exemplarischen ECU-Konfigurationsdefinition (<code>ECU Configuration Definition</code>) innerhalb der AUTOSAR Classic Platform (TPS ECU Configuration). Das Diagramm illustriert die relationale Einbettung eines konkreten BSW-Moduls (<code>Rte</code>) und dessen Konfigurationscontainer (<code>RteGeneration</code>) ausgehend von einer zentralen Definitionskollektion.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert drei Entitäten (UML-Objektinstanzen):</p>\n<ul class=\"fig-list\">\n<li><code>AUTOSARParameterDefinition : EcucDefinitionCollection</code>: Zentrale Sammlung aller Moduldefinitionen eines AUTOSAR-Systems.</li>\n<li><code>Rte : EcucModuleDef</code>: Moduldefinition für die Runtime Environment (RTE) mit den Attributwerten <code>upperMultiplicity = 1</code> und <code>lowerMultiplicity = 0</code>.</li>\n<li><code>RteGeneration : EcucParamConfContainerDef</code>: Containerdefinition für Generierungsparameter der RTE mit den Attributwerten <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen zwischen den Entitäten:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet-assoziative Referenz <code>+module</code> von <code>AUTOSARParameterDefinition</code> auf <code>Rte : EcucModuleDef</code> mit offener Pfeilspitze.</li>\n<li>Kompositionsbeziehung (ausgefüllte schwarze Raute) mit Rollenbezeichnung <code>+container</code> von <code>Rte : EcucModuleDef</code> zu <code>RteGeneration : EcucParamConfContainerDef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Definitionsmodell ohne dynamischen Laufzeit- oder Sequenzablauf. Die Instanzen bilden zur Entwurfs- bzw. Konfigurationszeit die hierarchische Metamodellstruktur ab: Eine <code>EcucDefinitionCollection</code> referenziert optionale Moduldefinitionen (<code>[0..1]</code>), welche per Komposition verpflichtende Container (<code>[1..1]</code>) zur Strukturierung der BSW-Konfigurationsparameter aggregieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert normativ die Struktur von Parameterspezifikationen in AUTOSAR ECU-Konfigurationsbeschreibungen (<code>.arxml</code>):</p>\n<ul class=\"fig-list\">\n<li><code>EcucModuleDef</code> dient als formale Definitionsgrundlage für konfigurierbare Parameter eines BSW-Moduls.</li>\n<li>Die Multiplizitäten regeln die Instanziierungsbedingungen: Das RTE-Modul ist im Kontext der Definition optional instanziierbar (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), während der Container <code>RteGeneration</code> bei Vorhandensein des Moduls genau einmal definiert sein muss (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Werkzeughersteller und Konfiguratoren müssen diese Kardinalitäten bei der Validierung von ECU-Konfigurationswerten gegen die Definitionsdateien zwingend durchsetzen.</li>\n</ul>"}, {"id": "FIG-9a6d5d91b1a03462", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzendiagramm) zur Spezifikation einer exemplarischen ECU-Konfigurationsdefinition (<code>ECU Configuration Definition</code>) innerhalb der AUTOSAR Classic Platform (TPS ECU Configuration). Das Diagramm illustriert die relationale Einbettung eines konkreten BSW-Moduls (<code>Rte</code>) und dessen Konfigurationscontainer (<code>RteGeneration</code>) ausgehend von einer zentralen Definitionskollektion.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert drei Entitäten (UML-Objektinstanzen):</p>\n<ul class=\"fig-list\">\n<li><code>AUTOSARParameterDefinition : EcucDefinitionCollection</code>: Zentrale Sammlung aller Moduldefinitionen eines AUTOSAR-Systems.</li>\n<li><code>Rte : EcucModuleDef</code>: Moduldefinition für die Runtime Environment (RTE) mit den Attributwerten <code>upperMultiplicity = 1</code> und <code>lowerMultiplicity = 0</code>.</li>\n<li><code>RteGeneration : EcucParamConfContainerDef</code>: Containerdefinition für Generierungsparameter der RTE mit den Attributwerten <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen zwischen den Entitäten:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet-assoziative Referenz <code>+module</code> von <code>AUTOSARParameterDefinition</code> auf <code>Rte : EcucModuleDef</code> mit offener Pfeilspitze.</li>\n<li>Kompositionsbeziehung (ausgefüllte schwarze Raute) mit Rollenbezeichnung <code>+container</code> von <code>Rte : EcucModuleDef</code> zu <code>RteGeneration : EcucParamConfContainerDef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Definitionsmodell ohne dynamischen Laufzeit- oder Sequenzablauf. Die Instanzen bilden zur Entwurfs- bzw. Konfigurationszeit die hierarchische Metamodellstruktur ab: Eine <code>EcucDefinitionCollection</code> referenziert optionale Moduldefinitionen (<code>[0..1]</code>), welche per Komposition verpflichtende Container (<code>[1..1]</code>) zur Strukturierung der BSW-Konfigurationsparameter aggregieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert normativ die Struktur von Parameterspezifikationen in AUTOSAR ECU-Konfigurationsbeschreibungen (<code>.arxml</code>):</p>\n<ul class=\"fig-list\">\n<li><code>EcucModuleDef</code> dient als formale Definitionsgrundlage für konfigurierbare Parameter eines BSW-Moduls.</li>\n<li>Die Multiplizitäten regeln die Instanziierungsbedingungen: Das RTE-Modul ist im Kontext der Definition optional instanziierbar (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), während der Container <code>RteGeneration</code> bei Vorhandensein des Moduls genau einmal definiert sein muss (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Werkzeughersteller und Konfiguratoren müssen diese Kardinalitäten bei der Validierung von ECU-Konfigurationswerten gegen die Definitionsdateien zwingend durchsetzen.</li>\n</ul>"}], "trans": [{"from": "FIG-9dcac809bcbb2b0d", "to": "FIG-77986867314985a1", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>In der Box <code>RteGeneration : EcucParamConfContainerDef</code> wurde eine horizontale Trennlinie zwischen dem Kopfbereich und dem Attributbereich eingefügt (an der rechten Außenkante minimal überstehend).</li>\n<li>Die Position der Verbindungslinie und der Pfeilspitze zur Box <code>Rte :EcucModuleDef</code> wurde vertikal leicht verschoben.</li>\n</ul>"}, {"from": "FIG-77986867314985a1", "to": "FIG-9a6d5d91b1a03462", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
